package canteen;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;
public class NotificationFrame extends JFrame {
 private final String user;private JTable table;private DefaultTableModel model;
 public NotificationFrame(String user,String role){this.user=user;AppStyle.setWindowIcon(this);setTitle("PIET | Notifications");setSize(900,560);setLocationRelativeTo(null);JPanel p=AppStyle.page("Notifications & stock alerts");model=new DefaultTableModel(new String[]{"ID","Time","Type","Message","Read"},0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);AppStyle.styleTable(table);table.getColumnModel().getColumn(0).setMinWidth(0);table.getColumnModel().getColumn(0).setMaxWidth(0);table.getColumnModel().getColumn(0).setPreferredWidth(0);JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));top.setOpaque(false);JButton refresh=AppStyle.button("Refresh alerts",AppStyle.BLUE),read=AppStyle.button("Mark selected read",AppStyle.NAVY);top.add(refresh);top.add(read);JPanel center=new JPanel(new BorderLayout(8,8));center.setOpaque(false);center.add(top,BorderLayout.NORTH);center.add(new JScrollPane(table),BorderLayout.CENTER);p.add(center,BorderLayout.CENTER);add(p);refresh.addActionListener(e->load());read.addActionListener(e->markRead());load();}
 private void load(){model.setRowCount(0);try(Connection c=DBConnection.getConnection()){try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT item_id,item_name,stock_quantity,COALESCE(min_stock_threshold,10) min_stock FROM food_items WHERE stock_quantity<=COALESCE(min_stock_threshold,10) ORDER BY stock_quantity")){while(r.next())model.addRow(new Object[]{0,new Timestamp(System.currentTimeMillis()),"STOCK",""+r.getString("item_name")+" has "+r.getInt("stock_quantity")+" units left (minimum "+r.getInt("min_stock")+")","Live"});}try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT notification_id,created_at,notification_type,message,is_read FROM notifications ORDER BY created_at DESC LIMIT 300")){while(r.next())model.addRow(new Object[]{r.getLong(1),r.getTimestamp(2),r.getString(3),r.getString(4),r.getBoolean(5)?"Yes":"No"});}}catch(SQLException e){JOptionPane.showMessageDialog(this,"Could not load notifications: "+e.getMessage());}}
 private void markRead(){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a notification first.");return;}int modelRow=table.convertRowIndexToModel(row);long id=Long.parseLong(model.getValueAt(modelRow,0).toString());if(id<=0){JOptionPane.showMessageDialog(this,"Live stock warnings are recalculated from current stock. Stored notifications can be marked read.");return;}try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE notifications SET is_read=TRUE,read_by=?,read_at=CURRENT_TIMESTAMP WHERE notification_id=? AND is_read=FALSE")){p.setString(1,user);p.setLong(2,id);p.executeUpdate();model.setValueAt("Yes",modelRow,4);}catch(SQLException e){JOptionPane.showMessageDialog(this,"This may be an auto-generated stock alert. Stored notifications can be marked read.\n"+e.getMessage());}}
}
